(() => {
'use strict';
const D=window.COURSE, main=document.querySelector('main'), key='china-shenlun-writing-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const external=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
let records={},storageProblem=false;
try{const v=JSON.parse(localStorage.getItem(key)||'{}');if(v&&typeof v==='object'&&!Array.isArray(v))records=v;else storageProblem=true;}catch{storageProblem=true;}
let timer;
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(timer);timer=setTimeout(()=>el.style.display='none',5500);}
function persist(){try{localStorage.setItem(key,JSON.stringify(records));storageProblem=false;return true;}catch{storageProblem=true;toast('浏览器保存失败。请立即导出当前草稿备份。');return false;}}
let lesson=D.lessons.find(x=>x.unit===2)||D.lessons[0];
const defaultLesson=lesson;
const fileLink=(name,label)=>`<a class="secondary" href="downloads/${encodeURIComponent(name)}" download>${esc(label)}</a>`;
function downloads(){return `<div class="actions downloads">${fileLink('了解中国与申论八课讲义.docx','合订版 Word ↓')}${fileLink('了解中国与申论八课讲义.md','合订版 Markdown ↓')}${fileLink('八课Markdown与Word.zip','八课完整下载包 ↓')}</div>`;}
function markdown(text){return text.split(/\n\s*\n/).map(block=>{const line=block.trim();if(!line)return '';const html=esc(line).replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g,(_,label,url)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).replace(/\n/g,'<br>');if(line.startsWith('# '))return '';if(line.startsWith('## '))return `<h2>${esc(line.slice(3))}</h2>`;if(line.startsWith('### '))return `<h3>${esc(line.slice(4))}</h3>`;if(/^原创(?:论证段|表达|分析段|建议段)：/.test(line))return '<p class="notice">本段写作示范已收在下方折叠区，可先完成自己的表达。</p>';return `<p>${html}</p>`;}).join('');}

function heading(k,t,p){return `<div class="eyebrow">${esc(k)}</div><h1>${esc(t)}</h1>${p?`<p class="intro">${esc(p)}</p>`:''}`;}
function sourceCard(s){return `<article class="source"><span class="badge">${esc(s.kind)}</span><h3>${esc(s.title)}</h3><p>${esc(s.publisher)}</p><p>定位：${esc(s.locator)}</p><p>已读：${esc(s.readScope)}</p><p>支持范围：${esc(s.applicability)}</p><p>核验范围：${esc(s.reviewScope)}</p><div class="source-meta">事件 / 通过 ${esc(s.eventDate)} · 页面发布 ${esc(s.publishedAt)}<br>本课段落核验 ${esc(s.checkedAt)}</div>${external(s.url,'打开官方原文')}</article>`;}
function today(){lesson=defaultLesson;main.innerHTML=`<section class="hero"><div>${heading('READ CHINA / WRITE WITH EVIDENCE','看懂中国，<br>写出有依据的答案。'.replace('<br>',''),'每天弄懂一个关系，解释一项工作，再把理解写出来。党的全面领导、人民立场与理论联系实际贯穿课程。')}<span class="badge red">${esc(D.stage)}</span></div><div class="hero-side"><strong>60 <small style="font-size:15px">min</small></strong>每日学习建议<br>计入原有八小时学习预算</div></section><div class="row-head"><h2>今天，从一个关系开始</h2><span class="subtle">第一天 / 党的领导</span></div><section class="panel lesson-feature"><div><span class="eyebrow">第2课 · 原文 → 工作 → 表达</span><h2>${esc(lesson.title)}</h2><p>${esc(lesson.question)}</p><span class="badge">${esc(lesson.status)}</span></div><a class="primary" href="#/lesson/${lesson.id}">开始学习 →</a></section><div class="row-head"><h2>一小时，留下自己的表达</h2><span class="subtle">时间是安排，非考场用时承诺</span></div><div class="steps">${[['5','闭卷回忆','昨天的一个关系'],['15','理解原文','今天的一个概念'],['15','读实际工作','找动作与机制'],['20','独立写作','先写再看示范'],['5','核对修订','留下一条规则']].map(x=>`<div class="step"><strong>${x[0]}<small> 分钟</small></strong><span>${x[1]}</span><small>${x[2]}</small></div>`).join('')}</div><div class="row-head"><h2>用三条线，把知识连起来</h2></div><div class="lines">${D.lines.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="notice">忙碌日可缩为20分钟。每周保留完整真题小题与阶段性限时作文；不做模拟卷。阅读量不能代替独立作答。</p><div class="row-head"><h2>官方渠道，各取所需</h2><a class="subtle" href="#/sources">看来源核查 →</a></div><div class="channel-grid">${D.channels.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.name)} ↗<small>${esc(x.use)}</small></a>`).join('')}</div>`;}
function course(){main.innerHTML=heading('COURSE / THE WHOLE PICTURE','八个单元，理解国家与工作。','先形成整体认识，再围绕具体问题学习。八课正文已备齐，先理解概念和工作机制，再完成各课独立输出。')+downloads()+`<div class="lines">${D.lines.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="grid">${D.units.map(u=>`<a class="unit" href="#/${u.lessonId?'lesson/'+u.lessonId:'unit/'+u.id}"><span class="number">${String(u.id).padStart(2,'0')}</span><h3>${esc(u.title)}</h3><p>${esc(u.question)}<br>${esc(u.intro)}</p><div class="unit-foot"><span class="badge ${u.lessonId?'red':''}">${esc(u.status)}</span><span>进入 →</span></div></a>`).join('')}</div>`;}
function pending(id){const u=D.units.find(x=>x.id===Number(id));if(!u){course();return;}main.innerHTML=`<a class="back" href="#/course">← 返回课程</a><div style="margin-top:25px">${heading('UNIT '+String(u.id).padStart(2,'0'),u.title,u.question)}</div><section class="panel pending"><span class="badge">待建设</span><h2 style="margin-top:18px">${esc(u.intro)}</h2><p>本页是学习目标与导航，详细课节尚未备齐。完成原文定位、工作机制、真实案例、写作任务和边界核查后，再发布完整课节。</p>${external(D.issues.course,'查看完整课程任务')}<p style="margin-top:20px"><a class="primary" href="#/lesson/${lesson.id}">先读一节已核查示范 →</a></p></section>`;}
function lessonPage(id){lesson=D.lessons.find(x=>x.id===id)||defaultLesson;const saved=records[lesson.id]||{};main.innerHTML=`<a class="back" href="#/course">← 返回八课课程</a><div style="margin-top:22px">${heading('第 '+lesson.unit+' 课 / 从理论到实际工作',lesson.title,lesson.question)}</div><span class="badge red">${esc(lesson.status)}</span><div class="actions">${fileLink(lesson.file.replace(/\.md$/,'.docx'),'本课 Word ↓')}${fileLink(lesson.file,'本课 Markdown ↓')}<a class="secondary" href="#/sources">十九章与来源对照 →</a><a class="secondary" href="#writing" data-scroll="writing">进入独立输出 ↓</a></div><article class="panel manuscript">${markdown(lesson.manuscript)}</article><section class="panel" id="writing"><span class="eyebrow">先独立写，再核对</span><h2 style="margin-top:10px">把理解变成自己的表达。</h2><p class="intro">${esc(lesson.prompt)}</p><label for="draft" class="label">我的草稿</label><textarea id="draft" maxlength="10000" placeholder="围绕本课任务，先写出你的理解……">${esc(saved.draft||'')}</textarea><div class="answer-tools"><span id="draft-status">${saved.updated?'上次保存 '+esc(saved.updated):'尚未保存'}</span><span id="count">${Array.from(saved.draft||'').length} 字符</span></div><div class="actions"><button class="primary" data-action="save">保存草稿</button><button class="secondary" data-action="freeze">冻结首稿</button><button class="secondary" data-action="export">导出我的作答 ↗</button></div><p class="subtle">保存后刷新可恢复；各课分别保存。冻结首稿只记录一次，后续保存不会覆盖。Word和Markdown含示范，独立练习可先用网页折叠模式。</p><div id="frozen">${saved.first?`<details><summary>查看冻结首稿</summary><div class="frozen">${esc(saved.first.text)}</div></details>`:''}</div><details id="example"><summary>我已独立写过，展开示范与核对</summary><p>${esc(lesson.example)}</p><ul class="checklist">${lesson.check.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="subtle">原创表达示范，非官方参考答案或评分标准。展开后记录已接触，不因此标记掌握。</p></details></section><section id="sources-in-lesson"><div class="row-head"><h2>本课来源核查</h2><span class="subtle">具体时点与边界见正文</span></div>${lesson.sourceIds.map(id=>sourceCard(D.sources.find(s=>s.id===id))).join('')}</section>`;
const draft=document.querySelector('#draft');draft.addEventListener('input',()=>{document.querySelector('#count').textContent=Array.from(draft.value).length+' 字符';document.querySelector('#draft-status').textContent='有未保存的修改';});document.querySelector('#example').addEventListener('toggle',e=>{if(e.target.open){records[lesson.id]={...(records[lesson.id]||{}),seenExampleAt:records[lesson.id]?.seenExampleAt||new Date().toISOString()};persist();}});}
function methods(){lesson=defaultLesson;main.innerHTML=heading('METHOD / FROM READING TO WRITING','读懂动作，也解释作用。','先看题干，再选择需要的分析角度。不是每道题都要写满下面六项。')+`<section class="panel"><div class="lines">${['问题对象','职责主体','关键卡点','具体动作','机制条件','结果反馈'].map(x=>`<span>${x}</span>`).join('')}</div><p class="reading">理论帮助你提出检查问题，题干与材料决定本题结论。工作建议还须核对权限、程序、资源、责任与反馈。</p></section>${lesson.uses.map(x=>`<div class="use-row"><strong>${esc(x[0])}</strong><span>${esc(x[1])}</span></div>`).join('')}<div class="panel"><h2>不要省掉中间的一步。</h2><p class="intro">从“采取措施”直接跳到“提高效能”，容易只剩套话。先解释措施改变了哪个环节，再判断是否有证据支持结果。</p><a class="primary" href="#/lesson/${lesson.id}">进入示范课，实际写一次 →</a></div>`;}
function sources(){main.innerHTML=heading('SOURCES / TRACE EVERY CLAIM','每条核心认识，都有来处。','原文、释义与教学提炼分开；政策部署与已经发生的结果分开。核验截至所列日期，不代表永远最新。')+downloads()+`<details class="chapter-index"><summary>《学习纲要》十九章与八课对照、实际选读范围</summary><article class="manuscript">${markdown(D.chapterIndex)}</article></details><label class="label" for="source-search">搜索八课来源</label><input class="search" id="source-search" type="search" placeholder="搜索标题、发布主体或内容定位"><div class="subtle" id="source-count">${D.sources.length} 条课节来源</div><div class="source-grid" id="source-list">${D.sources.map(sourceCard).join('')}</div><div class="row-head"><h2>常用官方渠道</h2></div><div class="channel-grid">${D.channels.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.name)} ↗<small>${esc(x.use)}</small></a>`).join('')}</div>`;document.querySelector('#source-search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase(),xs=D.sources.filter(s=>JSON.stringify(s).toLowerCase().includes(q));document.querySelector('#source-count').textContent=xs.length+' 条匹配来源';document.querySelector('#source-list').innerHTML=xs.length?xs.map(sourceCard).join(''):'<p class="notice">没有匹配来源，请换一个关键词。</p>';});}
function about(){main.innerHTML=heading('PROJECT / SCOPE & EVIDENCE','先写齐讲义，再按证据教学。','八课已备齐正文、Word与Markdown。内容建设和个人效果分别验收。')+`<section class="panel"><h2>本次已落地的范围</h2><p class="intro">八课完整讲义初稿、十九章原文定位与选读记录、真实案例及写作任务、九份Word、Markdown和打包下载已落地。八课网页直接使用讲义正文，各课独立保存草稿。用户迁移效果仍待独立练习验证。</p><p class="intro">准确记忆必要的官方概念，理解复述机制，按需调用案例。压缩以不改变含义为边界；不要求全库逐字默写，不承诺万能答案。</p></section><div class="grid">${[['总工程','epic','课程整体建设与验收'],['网站与治理','site','本轮实现、验证与发布'],['完整课程','course','逐课原文、机制、案例与应用'],['来源与迁移','transfer','来源维护与真实独立表现']].map(x=>`<a class="unit" href="${D.issues[x[1]]}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">GITHUB ISSUE</span><h3 style="margin-top:12px">${x[0]} ↗</h3><p>${x[2]}</p></a>`).join('')}</div><p class="notice">未配置自动更新或定时推送。资料依实际核查更新；阅读、上线和掌握分别记录。</p><p class="notice">浏览器记录不跨设备同步。导出含你的个人作答，请自行保存，不上传公开仓库。</p><p>${external('https://github.com/3013038780-design/civilserviceexam/tree/codex/china-shenlun-course/sites/china-shenlun','查看需求、README与AGENTS')}</p>`;}
function render(){const [view='today',id]=location.hash.replace(/^#\/?/,'').split('/');let nav=view==='lesson'||view==='unit'?'course':view;document.querySelectorAll('[data-nav]').forEach(x=>{x.classList.toggle('active',x.dataset.nav===nav);if(x.dataset.nav===nav)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current');});document.querySelector('#breadcrumb').textContent=({today:'今日学习',course:'八单元课程',methods:'机制与写法',sources:'原文与来源',about:'建设依据',lesson:'课程 / 完整讲义',unit:'课程 / 待建设单元'})[view]||'今日学习';if(view==='course')course();else if(view==='lesson'&&D.lessons.some(x=>x.id===id))lessonPage(id);else if(view==='unit')pending(id);else if(view==='methods')methods();else if(view==='sources')sources();else if(view==='about')about();else today();window.scrollTo(0,0);if(storageProblem)toast('浏览器存储不可用或原记录异常，请导出备份后再继续。');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-scroll]');if(!b)return;if(b.dataset.scroll){e.preventDefault();document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}const action=b.dataset.action,draft=document.querySelector('#draft')?.value||'',old=records[lesson.id]||{};if(action==='save'){records[lesson.id]={...old,draft,updated:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})};if(persist()){document.querySelector('#draft-status').textContent='已保存到当前浏览器';toast('草稿已保存');}}else if(action==='freeze'){if(old.first){toast('首稿已经冻结，后续草稿不会覆盖它。');return;}if(!draft.trim()){toast('先写一点内容，再冻结首稿。');return;}records[lesson.id]={...old,draft,first:{text:draft,at:new Date().toISOString(),seenExample:!!old.seenExampleAt}};if(persist()){document.querySelector('#frozen').innerHTML=`<details><summary>查看冻结首稿</summary><div class="frozen">${esc(draft)}</div></details>`;toast('首稿已冻结；仍可继续修改草稿。');}}else if(action==='export'){const out={schema:'china-shenlun-writing/v1',exportedAt:new Date().toISOString(),records:{...records,[lesson.id]:{...old,draft}}},blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='申论独立作答-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前草稿及冻结记录');}});
window.addEventListener('beforeunload',e=>{const el=document.querySelector('#draft');if(el&&el.value!==(records[lesson.id]?.draft||'')){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',render);render();
})();
